export const COASTERS_COLLECTION = {
  name: 'Roller Coasters', title: 'Roller Coasters',
  attrs: [
    { name: 'Coaster', type: 'categorical' },
    { name: 'Park', type: 'categorical' },
    { name: 'City', type: 'categorical' },
    { name: 'Type', type: 'categorical' },
    { name: 'Design', type: 'categorical' },
    { name: 'Age_Group', type: 'categorical' },
    { name: 'Inversions', type: 'categorical' },
    { name: 'Top_Speed', type: 'numeric', unit: 'mph' },
    { name: 'Max_Height', type: 'numeric', unit: 'ft' },
    { name: 'Drop', type: 'numeric', unit: 'ft' },
    { name: 'Length', type: 'numeric', unit: 'ft' },
    { name: 'Duration', type: 'numeric', unit: 'sec' },
    { name: 'Year_Opened', type: 'numeric' },
    { name: 'Num_of_Inversions', type: 'numeric' },
    { name: 'latitude', type: 'numeric' },
    { name: 'longitude', type: 'numeric' },
  ],
};

const ITEM_BATCH = 20;
const itemCount = async (api) => (await api('get', 'dataContext[Roller Coasters].itemCount'))?.values ?? 0;
const tableId = async (api) => {
  const list = await api('get', 'componentList');
  return (list?.values ?? []).find((c) => /caseTable/i.test(c.type))?.id;
};

/** Create the dataset and a case table if they are not already there. */
export async function ensureCoasters(api, { force = false } = {}) {
  // Ask before adding data: CODAP can stall for ~20 s after taking in 157
  // items, long enough for even a retried read to time out.
  const hadTable = (await tableId(api)) != null;
  const existing = await api('get', 'dataContext[Roller Coasters]');
  if (existing?.success && force) await api('delete', 'dataContext[Roller Coasters]');
  if (!existing?.success || force) {
    await settle('dataset',
      () => api('create', 'dataContext', {
        name: 'Roller Coasters', title: 'Roller Coasters', collections: [COASTERS_COLLECTION],
      }),
      async () => (await api('get', 'dataContext[Roller Coasters]'))?.success,
    );
    for (let i = 0; i < COASTERS.length; i += ITEM_BATCH) {
      const target = Math.min(i + ITEM_BATCH, COASTERS.length);
      await settle(`items to ${target}`,
        () => api('create', 'dataContext[Roller Coasters].item', COASTERS.slice(i, target)),
        async () => (await itemCount(api)) >= target,
      );
    }
  }
  if (hadTable) return;
  await settle('case table',
    // No position: CODAP places it, rather than under the plugin's own tile.
    () => api('create', 'component', {
      type: 'caseTable', dataContext: 'Roller Coasters', name: 'Roller Coasters',
      dimensions: { width: 620, height: 260 },
    }),
    async () => (await tableId(api)) != null,
  );
}
